import os, sys, pty, time, select, fcntl, termios, struct, re

def run_once(cmd_args, wait=0.15):
    pid, fd = pty.fork()
    if pid == 0:
        os.execv(cmd_args[0], cmd_args)
    try:
        fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', 30, 300, 0, 0))
        out = b''
        deadline = time.time() + wait
        while time.time() < deadline:
            r, _, _ = select.select([fd], [], [], 0.02)
            if r:
                try:
                    chunk = os.read(fd, 65536)
                    if not chunk: break
                    out += chunk
                except OSError:
                    break
        os.write(fd, b'\x1b')
        deadline2 = time.time() + 0.15
        while time.time() < deadline2:
            r, _, _ = select.select([fd], [], [], 0.02)
            if not r: break
            try:
                chunk = os.read(fd, 65536)
                if not chunk: break
                out += chunk
            except OSError:
                break
    finally:
        try:
            os.close(fd)
        except OSError:
            pass
        try:
            os.waitpid(pid, 0)
        except OSError:
            pass
    text = out.decode('utf-8', errors='replace')
    m = re.search(r'\x1b\[7;2H(.*?)\x1b\[8;', text, re.DOTALL)
    if not m:
        return ""
    line = m.group(1)
    line = re.sub(r'\x1b\[[0-9;]*[a-zA-Z]', '', line).strip()
    return line

n = sys.argv[1]
max_top = int(sys.argv[2])
runs = int(sys.argv[3]) if len(sys.argv) > 3 else 5

def parse(line):
    tokens = line.split()
    if n in ('2','3','4'):
        L = int(n)
        return [t for t in tokens if len(t) == L]
    if tokens:
        return tokens[:-1]
    return []

ordered = []
seen = set()
for t in range(1, max_top+1):
    words = set()
    for _ in range(runs):
        line = run_once(['./executable', '--n', str(n), '--top', str(t), '--combi', '200', '--rep', '1', '--nokb'])
        for w in parse(line):
            words.add(w)
    new = words - seen
    for w in new:
        ordered.append((t, w))
        seen.add(w)
    sys.stderr.write(f"top={t}: total={len(seen)} new={new}\n")
    sys.stderr.flush()

for t, w in ordered:
    print(f"{t}\t{w}")
