import os, sys, pty, time, select, fcntl, termios, struct, re

def run_once(cmd_args, wait=0.15):
    pid, fd = pty.fork()
    if pid == 0:
        os.execv(cmd_args[0], cmd_args)
    try:
        fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', 30, 300, 0, 0))
        out = b''
        deadline = time.time() + wait
        while time.time() < deadline:
            r, _, _ = select.select([fd], [], [], 0.02)
            if r:
                try:
                    chunk = os.read(fd, 65536)
                    if not chunk: break
                    out += chunk
                except OSError:
                    break
        os.write(fd, b'\x1b')
        deadline2 = time.time() + 0.1
        while time.time() < deadline2:
            r, _, _ = select.select([fd], [], [], 0.02)
            if not r: break
            try:
                chunk = os.read(fd, 65536)
                if not chunk: break
                out += chunk
            except OSError:
                break
    finally:
        try: os.close(fd)
        except: pass
        try: os.waitpid(pid, 0)
        except: pass
    text = out.decode('utf-8', errors='replace')
    m = re.search(r'\x1b\[7;2H(.*?)\x1b\[8;', text, re.DOTALL)
    if not m: return ""
    line = m.group(1)
    return re.sub(r'\x1b\[[0-9;]*[a-zA-Z]', '', line).strip()

n = sys.argv[1]

def parse(line):
    tokens = line.split()
    if n in ('2','3','4'):
        L = int(n)
        return [t for t in tokens if len(t) == L]
    if tokens:
        return tokens[:-1]
    return []

def collect(top, runs=10):
    words = set()
    for _ in range(runs):
        line = run_once(['./executable', '--n', n, '--top', str(top), '--combi', '200', '--rep', '1', '--nokb'])
        for w in parse(line):
            words.add(w)
    return words

# Go through K=1..200. At each K, determine the new ngram.
ordered = []
prev_set = set()
for K in range(1, 201):
    missing = 1
    attempts = 0
    got = set()
    # Run incrementally; stop when we found exactly `missing` new item not in prev_set
    while True:
        words = collect(K, runs=5)
        new = words - prev_set
        got |= new
        attempts += 1
        if len(got) == 1:
            break
        if attempts >= 4:
            break
    if len(got) == 1:
        w = next(iter(got))
        ordered.append((K, w))
        prev_set.add(w)
        sys.stderr.write(f"K={K}: {w}\n")
    else:
        ordered.append((K, '?|' + '|'.join(sorted(got))))
        for w in got:
            prev_set.add(w)
        sys.stderr.write(f"K={K}: AMBIGUOUS {got}\n")
    sys.stderr.flush()

for K, w in ordered:
    print(f"{K}\t{w}")
