        os.write(fd, b'\x1b')
        deadline2 = time.time() + 0.1
        while time.time() < deadline2:
            r, _, _ = select.select([fd], [], [], 0.02)
            if not r: break
            try:
                chunk = os.read(fd, 65536)
                if not chunk: break
                out += chunk
            except OSError:
                break
    finally:
        try: os.close(fd)
        except: pass
        try: os.waitpid(pid, 0)
        except: pass
    text = out.decode('utf-8', errors='replace')
    m = re.search(r'\x1b\[7;2H(.*?)\x1b\[8;', text, re.DOTALL)
    if not m: return ""
    line = m.group(1)
    return re.sub(r'\x1b\[[0-9;]*[a-zA-Z]', '', line).strip()

n = sys.argv[1]
infile = sys.argv[2]

def parse(line):
    tokens = line.split()
    if n in ('2','3','4'):
        L = int(n)
        return [t for t in tokens if len(t) == L]
    if tokens:
        return tokens[:-1]
    return []

# Load data
entries = []  # list of (rank, word or '?')
with open(infile) as f:
    for line in f:
        r, w = line.rstrip('\n').split('\t')
        entries.append((int(r), w))

# Find spans of ambiguity
# Rank has ? or contains '|' (multiple candidates)
i = 0
# Determine rank -> final word
final = {}
for r, w in entries:
    if w == '?' or '|' in w:
        final[r] = None  # to be resolved
    else:
        final[r] = w

# Find unresolved positions: for each '?', we missed rank at K.
# For each '|', multiple candidates but we don't know order.

# Strategy: walk through the list. When we see a ? followed by later |, we have a window:
# e.g., 161='?', 162='ga|qu' means 161 and 162 are from {ga, qu}. We need to determine which.
# Test at top=161: is 'ga' present? If yes, ga=161, qu=162. Else qu=161.

# Collect windows: a window starts at the first ? or | and ends at the last | after consecutive uncertainty
def test_presence(target, top, runs=30):
    """Check if target appears in samples at top=K"""
    for _ in range(runs):
        line = run_once(['./executable', '--n', n, '--top', str(top), '--combi', '200', '--rep', '1', '--nokb'])
        if target in parse(line):
            return True
    return False

# Gather unresolved ranges
ranges = []
cur_start = None
for r, w in entries:
    if w == '?' or '|' in w:
        if cur_start is None:
            cur_start = r
    else:
        if cur_start is not None:
            ranges.append((cur_start, r-1))
            cur_start = None
if cur_start is not None:
    ranges.append((cur_start, entries[-1][0]))

sys.stderr.write(f"Unresolved ranges: {ranges}\n")

for (a, b) in ranges:
    # Collect candidate ngrams
    candidates = set()
    for r in range(a, b+1):
        w = dict(entries)[r]
        if '|' in w:
            for x in w.split('|'):
                candidates.add(x)
    # Now we have N candidates for ranks a..b (should be b-a+1 candidates)
    sys.stderr.write(f"Range {a}-{b}: candidates={candidates}\n")
    # For each rank from a upward, determine which candidate
